const i={yingshe:{bibi:"現物",bibidingdan:"現物注文",bibijiaoyi:"現物取引",jiamihuobi:"無期限契約",miaoheyue:"決済契約",miaoheyuejiaoyi:"決済契約取引"},jiaoyi:{xianhuomingcheng:"現物名称"},aurexion:{jianguanwenjian:"規制文書"},rwa_283:{jiaru:"今すぐRWAに参加",biaoti:"超低手数料、卓越したセキュリティ、高い取引上限、そして最高水準のサポート",xiazai:"アプリをダウンロード",jiaoyiliang:"24時間取引量",guanyu:"RWAについて",guanyuxiangqing:"RWAは、投資、アドバイザリー、リスク管理ソリューションを提供する世界有数の企業です。当社は顧客に対して受託者責任を負っています。将来に向けた投資を支援し、従業員を鼓舞し、地域社会を支援しています。詳細は動画をご覧ください。",jieshao:"フォーチュン誌が選ぶ世界で最も称賛される企業",jieshaoxiangqing:"当社は12年連続でフォーチュン誌の「世界で最も称賛される企業」に選出され、証券および資産運用業界で第1位を獲得しました。",weishenme:"RWAを選ぶ理由",weishenmexiangqing:"RWAが多くの投資家から信頼されている理由は、業界内で最も幅広い選択肢を提供しているからです。",weishenmexiangqing1:"過去5年間で18兆ドルの純資金流入",weishenmexiangqing2:"3,500万人以上の米国人の投資と退職後の貯蓄を支援",weishenmexiangqing3:"米国の19万人以上の金融アドバイザーがRWAを選択",huoban:"パートナー",huobanxiangqing:"近年、RWAはAI分野に積極的に投資し、インフラ、チップ技術、データ分析、持続可能な開発において多くのAI企業と提携しています。",huoban1:"グローバルAIインフラ投資パートナーシップ（AIP）",huoban11:"2024年9月、RWAはMicrosoft、Mubadala、GIPとともにAIPを設立しました。",huoban2:"AIチップ企業Groqへの投資",huoban22:"2024年8月、RWAはGroqの6億4,000万ドルの資金調達を主導しました。",huoban3:"AI分析企業Pyramid Analyticsへの投資",huoban33:"2024年11月、RWAはPyramid Analyticsに5,000万ドルを投資しました。",huoban4:"Clarity AIとの戦略的提携",huoban44:"2021年以降、RWAはClarity AIに投資し、その技術をAladdinに統合しています。",huoban5:"これらの提携を通じて、RWAはAIエコシステムにおける戦略的展開を加速させています。",chongti:"迅速な入出金",chongtixiangqing:"複数の一般的な決済手段に対応し、迅速な入出金を実現",huanying:"RWAサービスへようこそ",baipishu:"ホワイトペーパー",chengyuandengjice:"会員名簿",gongsizhangcheng:"定款",gupiaozhengshu:"株式証書",huiyijilu:"議事録",zhucezhengshu:"登録証明書",shuihao:"納税者番号",weijiaoyiersheng:"取引のために生まれた",guanlianzhanghu:"関連アカウント",yizhixingdingdan:"約定済み注文",xinwen:"ニュース",cishan:"慈善",efepeishou:"ETF割当",rineijiaoyi:"デイトレード"}};export{i as default};
